import logging
import re
import time
from collections import deque
from contextlib import suppress
from datetime import datetime
from threading import Lock, RLock, Thread

from ..exceptions import (
    InvalidSerialNumberError,
    LoginFailedError,
    RMODSnapshotSecuringError,
    ROMMemoryFullError,
    RMODBusyError,
)
from .utils import retry

logger = logging.getLogger(name="rmod_serial_interface")
logger.addHandler(logging.NullHandler())


REBOOT_ONGOING_LOGS = [
    "the system is going down for reboot NOW!",
    "Sending processes the TERM signal",
    "Rebooting...",
    "Starting Reboot...",
    "Stopped RFSW Swman systemd startup scripts service",
    "Stopping Login Service...",
    "Stopping Permit User Sessions...",
    "Stopping System Logging Service...",
    "Unmounting /mnt/factory...",
    "Unmounting /mnt/runtime...",
    "Unmounting /tmp...",
]
REBOOT_ENDED_LOGS = [
    "Last login:",
    "Wind River Linux",
    "Full DFE (Mars) image",
    "Yocto Project Reference Distro",
    "Yocto distribution",
    "NOKIA RFSW LINUX",
    re.escape("--=---+---=--*"),
    re.escape("## ###      ### ##"),
    re.escape("++  ++++   +++       +++ +++      +++   ++++++++"),
]
ENTER_UBOOT_PRESS_KEY_LOGS = [
    "Press 'ccc' to enter u-boot",
    "Hit any key to stop autoboot",
    r"Autoboot in \d+ seconds",
    r"Press \d+x <ESC> to enter U-Boot",
]
EARLY_STARTUP_LOGS = ["eMMC Boot Mode", "Boot:  EMMC"]
CONSOLE_BLOCK_LOGS = ["Console disabled for debug purposes", "restore console send double BREAK command"]


class DefaultRMODInterface:
    def __init__(self, connector, session_logger):
        self._ru = connector
        self._session_logger = session_logger
        self._output_buffer = ""
        self.login = "root"
        self.password = ""
        self.login_prompt_regex = re.compile(r"(?<!last\s)login:", flags=re.I)
        self.password_prompt_regex = re.compile(r"Password:", flags=re.I)
        self.enter_uboot_regex = re.compile(rf"{'|'.join(ENTER_UBOOT_PRESS_KEY_LOGS)}", re.I)
        self.enter_uboot_timeout = 3
        self.reboot_ongoing_logs_regex = re.compile(rf"{'|'.join(REBOOT_ONGOING_LOGS)}", re.I)
        self.reboot_ended_logs_regex = re.compile(rf"{'|'.join(REBOOT_ENDED_LOGS)}", re.I)
        self.early_startup_regex = re.compile(rf"{'|'.join(EARLY_STARTUP_LOGS)}", re.I)
        self.console_blocked_regex = re.compile(rf"{'|'.join(CONSOLE_BLOCK_LOGS)}", re.I)
        self.serial_number_path = "/mnt/factory/configs/unit/module_serial_number.txt"
        self._serial_number = None
        self.auto_env_path = "/mnt/runtime"
        self.snapshot_cmd = "ccsShell.sh log -a -c full -z {snapshot_path}"
        self.snapshot_name = "snapshot_{sn}_{ts}.zip"
        self.snapshot_success_print_regex = re.compile(r"AaSysComUserDeregister succeed!")
        self.connection_timeout = 120
        self.login_prompt_timeout = 30
        self.default_cmd_timeout = 3
        self.inactivity_timer = 60
        self._join_timeout = 30
        self._last_read_ts = None
        self.after_login_confirmation_timeout = 15
        self._disconnect_requested = False
        self._state = RMODState()
        self._connector_mutex = RLock()
        self._active_output_queue = deque()
        self._active_reading_depth = 0
        self._line_buffer = ""
        self._line_timeout = 0.5
        self._last_char_ts = None
        self._echo_timeout = 2
        self._echo_retry_count = 3
        self._reader_thread = Thread(name=f"Connector (port={connector.port})", target=self._reader_loop, daemon=True)
        self._exc = None
        self._custom_shell_prompt_regex = None
        self._known_logins = {self.login, "root"}

    @property
    def shell_prompt_regex(self):
        if self._custom_shell_prompt_regex is not None:
            return self._custom_shell_prompt_regex
        login_patterns = [rf"\[?{login}@.*\n?[$#]\s?|made:~\$" for login in self._known_logins]
        static_patterns = [
            r"(rfsw|stratix)\S*?:[/~]\S*[$#]\s?",
            r"\[5g-poco-mk4.*?\].*?[~/]\r*\n?[$#]\s*?",
            r"ftp@made-Node\d+:/home/root[$#]\s*?",
        ]
        return "|".join(login_patterns + static_patterns)

    @shell_prompt_regex.setter
    def shell_prompt_regex(self, value):
        self._custom_shell_prompt_regex = value

    def set_credentials(self, login, password):
        self._known_logins.add(login)
        self.login = login
        self.password = password

    def _restore_connection(self, timeout):
        try:
            self._ru.close()
            self._ru.open(timeout=timeout)
            self._session_logger.log_debug("Connection restored.")
            logger.warning(f"[{self._serial_number}] Connection restored.")
            self._state.connected = True
        except Exception as e:
            self._session_logger.log_debug(f"Reconnecting failed; {e.__class__.__name__}: {e}")
            logger.error(f"[{self._serial_number}] Reconnecting failed;", exc_info=True)
            logger.debug(f"[{self._serial_number}] State: {self._state}")

    def _maintain_connection(self, timeout):
        if self._ru.is_closed():
            if self._state.connected is True:
                self._session_logger.log_debug("Lost connection to device. reconnecting...")
                logger.warning(f"[{self._serial_number}] Lost connection to device. reconnecting...")
            self._state.connected = False
            self._state.logged_in = False
            self._restore_connection(timeout)
        else:
            self._state.connected = True

    def _reader_loop(self):
        self._last_read_ts = time.monotonic()
        try:
            while not self._disconnect_requested:
                with self._connector_mutex:
                    self._maintain_connection(timeout=5)
                    if self._state.connected:
                        self._poll_rmod()
                    if self._state.sending_possible and time.monotonic() - self._last_read_ts > self.inactivity_timer:
                        self._ping()
                        self._last_read_ts = time.monotonic()
                time.sleep(0.03)
        except Exception as e:
            logger.error(f"[{self._serial_number}] Exception in reader thread;", exc_info=True)
            logger.debug(f"[{self._serial_number}] State: {self._state}")
            self._exc = e

    def _poll_rmod(self):
        data = self._ru.read_available()
        if data:
            self._last_char_ts = time.monotonic()
            self._last_read_ts = time.monotonic()
            for char in data:
                self._process_char(char)
        elif self._line_buffer and self._last_char_ts:
            if time.monotonic() - self._last_char_ts > self._line_timeout:
                self._flush_line_buffer()

    def _process_char(self, char):
        if self._reading_actively:
            self._active_output_queue.append(char)
        else:
            self._output_buffer += char
        self._line_buffer += char
        if char == '\n' or char == '\r':
            self._flush_line_buffer()

    def _flush_line_buffer(self):
        if self._line_buffer:
            line = self._line_buffer.strip('\r\n')
            if line:
                self._session_logger.log_read(line)
                self._resolve_state_transition(line)
            self._line_buffer = ""

    @property
    def _reading_actively(self):
        return self._active_reading_depth > 0

    def _start_active_reading(self):
        if self._active_reading_depth == 0:
            self._active_output_queue.clear()
        self._active_reading_depth += 1

    def _stop_active_reading(self):
        if self._active_reading_depth > 0:
            self._active_reading_depth -= 1

    def _resolve_state_transition(self, msg):
        self._check_login_prompt_transition(msg)
        self._check_uboot_transition(msg)
        self._check_console_block_transition(msg)
        self._check_reset_transition(msg)

    def _check_login_prompt_transition(self, msg):
        if self.login_prompt_regex.search(msg):
            self._state.logged_in = False
            self._state.login_possible = True
            self._state.uboot_detected = False

    def _check_uboot_transition(self, msg):
        if msg.lstrip().lower().startswith("u-boot") or self.early_startup_regex.search(msg):
            if self._state.uboot_detected is False:
                self._state.uboot_detected = True
                self._state.reboot_detected = True
                self._state.logged_in = False
                self._state.login_possible = False
                logger.warning(f"[{self._serial_number}] U-boot startup detected! Suppressing key strokes...")
        elif self.enter_uboot_regex.search(msg):
            self._state.uboot_detected = True
            self._state.reboot_detected = True
            self._state.logged_in = False
            self._state.login_possible = False
            logger.warning(
                f"[{self._serial_number}] Autoboot delay/U-boot enter press key prompt detected! "
                f"Allowing key strokes in {self.enter_uboot_timeout}s..."
            )
            time.sleep(self.enter_uboot_timeout)
            self._state.uboot_detected = False

    def _check_console_block_transition(self, msg):
        if self.console_blocked_regex.search(msg):
            self._state.console_blocked = True

    def _check_reset_transition(self, msg):
        if self.reboot_ongoing_logs_regex.search(msg):
            self._state.reboot_detected = True
            self._state.login_possible = False
            self._state.logged_in = False
        elif self.reboot_ended_logs_regex.search(msg):
            self._state.reboot_detected = False

    def connect(self):
        self._ru.open(timeout=self.connection_timeout)
        self._state.connected = True
        self._reader_thread.start()
        time.sleep(self.enter_uboot_timeout)

    def first_log_in(self):
        if self._is_login_required():
            self._run_login_procedure()
        else:
            self._confirm_correct_user()
        self._state.logged_in = True
        self._state.login_possible = True

    def log_in(self):
        if self._is_login_required():
            self._run_login_procedure()
        self._state.logged_in = True
        self._state.login_possible = True

    def _is_login_required(self, attempt_logout=True):
        output, timedout = self._execute_cmd_for_login_procedure(
            "",
            timeout=self.login_prompt_timeout,
            extra_prompts=[self.login_prompt_regex],
            include_pattern_in_output=True,
        )
        if timedout:
            if not output and attempt_logout:
                self._session_logger.log_debug("Possible console block. Trying unblocking...")
                try:
                    self.unblock_console()
                except NotImplementedError:
                    self._session_logger.log_debug("Unblocking not supported with NetworkConnector")
            if attempt_logout:
                self._execute_cmd_for_login_procedure("logout", timeout=0.5)
                return self._is_login_required(attempt_logout=False)
            raise LoginFailedError(f"Could not match neither shell prompt nor login prompt in output: {repr(output)}")
        elif self.login_prompt_regex.search(output) is not None:
            return True
        return False

    def _run_login_procedure(self):
        output, timedout = self._execute_cmd_for_login_procedure(
            self.login,
            timeout=self.default_cmd_timeout,
            extra_prompts=[self.password_prompt_regex],
            include_pattern_in_output=True,
        )
        if timedout:
            if self._is_login_required(attempt_logout=False):
                raise LoginFailedError(
                    f"Could not match neither shell prompt nor password prompt in output: {repr(output)}"
                )
        elif self.password_prompt_regex.search(output) is not None:
            output, timedout = self._execute_cmd_for_login_procedure(
                self.password, timeout=self.after_login_confirmation_timeout, wait_echo=False
            )
            if timedout and self._is_login_required(attempt_logout=False):
                raise LoginFailedError(f"Could not match shell prompt in output: {repr(output)}")

    def _confirm_correct_user(self):
        output, _ = self._execute_cmd_for_login_procedure("whoami", timeout=self.default_cmd_timeout)
        if self.login not in output:
            self._execute_cmd_for_login_procedure(
                "logout", timeout=self.default_cmd_timeout, extra_prompts=[self.login_prompt_regex]
            )
            self.first_log_in()

    @property
    def serial_number(self):
        if self._serial_number is None:
            self._serial_number = self._get_serial_number()
        return self._serial_number

    @retry(2, exceptions=(TimeoutError, InvalidSerialNumberError))
    def _get_serial_number(self):
        if self._file_exists(self.serial_number_path):
            cmd = f"cat {self.serial_number_path}"
        else:
            cmd = "echo $(hostname)-id-$(date +%s)"
        output, timedout = self.execute_cmd(cmd, elevated=True)
        if timedout:
            raise TimeoutError("Did not receive serial number from RU. Check connection log.")
        sn = self._validate_serial_number(output)
        return sn

    @staticmethod
    def _validate_serial_number(sn):
        for line in reversed(sn.split("\n")):
            line = line.strip()
            if ((9 < len(line) < 14) and len(line.split()) == 1) or "-id-" in line:
                return line
        raise InvalidSerialNumberError(f"Invalid serial number received from RU: {repr(sn)}")

    @retry(1, exceptions=RMODSnapshotSecuringError)
    def take_snapshot(self, timeout=180):
        if "-id-" in self.serial_number:
            raise RMODSnapshotSecuringError("Unable to take snapshot on slave node connection")
        snapshot_name = self.snapshot_name.format(
            sn=self.serial_number, ts=datetime.now().strftime("%y.%m.%d_%H-%M-%S")
        )
        snapshot_collecting_path = f"/ram/{snapshot_name}"
        output, timedout = self.execute_cmd(
            self.snapshot_cmd.format(snapshot_path=snapshot_collecting_path), elevated=True, timeout=timeout
        )
        self._validate_snapshot_securing(cmd_output=output, has_timedout=timedout)
        self._check_snapshot_exists(snapshot_collecting_path)
        snapshot_target_path = f"{self.auto_env_path}/{snapshot_name}"
        self._move_snap_to_rom(snapshot_collecting_path, snapshot_target_path)
        self._check_snapshot_exists(snapshot_target_path)
        return snapshot_target_path

    def _validate_snapshot_securing(self, cmd_output, has_timedout):
        if self.snapshot_success_print_regex.search(cmd_output) is None:
            if has_timedout:
                raise RMODSnapshotSecuringError("Snapshot securing timed out before reaching success print")

    def _check_snapshot_exists(self, snapshot_path):
        if not self._file_exists(snapshot_path):
            raise RMODSnapshotSecuringError(f"Snapshot has not been created in {snapshot_path} location.")

    def _file_exists(self, filepath):
        output, timedout = self.execute_cmd(
            f"test -e {filepath} && echo $?$?$?$?$?$?$?$? || echo $?$?$?$?$?$?$?$?", elevated=True
        )
        if timedout:
            raise TimeoutError(f"Did not receive confirmation of file {filepath} existence")
        return "00000000" in output

    def _move_snap_to_rom(self, source_path, target_path):
        timeout = 90
        output, timedout = self.execute_cmd(f"mv {source_path} {target_path}", elevated=True, timeout=timeout)
        if "No space left on device" in output:
            self.send_cmd(f"rm -f {target_path}", elevated=False)
            raise ROMMemoryFullError("Disk usage 100% after moving snapshot")
        if timedout:
            self.execute_cmd("\03", timeout=15)
            self.send_cmd(f"rm -f {target_path}", elevated=False)
            raise TimeoutError(f"while moving snapshot file from {source_path} to {target_path}. Timeout = {timeout}.")

    def _wait_for_sending_state(self, timeout=30):
        t = time.monotonic() + timeout
        while not self._state.sending_possible:
            if time.monotonic() > t:
                if not self._state.connected:
                    raise ConnectionError(f"Timeout ({timeout}s) occured while waiting for connection restore")
                else:
                    raise RMODBusyError(f"Timeout ({timeout}s) occured while waiting for reboot/startup"
                                        f" procedure to complete")
            time.sleep(1)
        if self._state.console_blocked:
            self.unblock_console()

    def _raise_if_not_sending_state(self, echo_buffer=None):
        if not self._state.sending_possible:
            if echo_buffer is not None:
                for char in reversed(echo_buffer):
                    self._active_output_queue.appendleft(char)
            if not self._state.connected:
                raise ConnectionError("Send aborted: Lost connection to RU")
            reason = "uboot detected" if self._state.uboot_detected else "reboot detected"
            raise RMODBusyError(f"Send aborted: RU not in sending state ({reason})")

    def unblock_console(self):
        self._session_logger.log_debug("Sending double BREAK cmd...")
        self._ru.send_break()
        time.sleep(0.1)
        self._ru.send_break()
        self._state.console_blocked = False

    def send_cmd(self, cmd, elevated=False, wait_echo=True):
        self._wait_for_sending_state(self.connection_timeout)
        with self._connector_mutex:
            self._send(cmd, elevated, wait_echo=wait_echo)

    def _send(self, cmd, elevated=False, wait_echo=True, skip_log_in=False):
        if elevated:
            cmd = self._elevate_command(cmd)
        cmd += "\r"
        if not skip_log_in and not self._state.logged_in:
            self.log_in()
        self._session_logger.log_write(cmd.strip() if cmd.strip() else "<ENTER>")
        if wait_echo:
            self._send_with_echo_ack(cmd)
        else:
            self._send_with_no_ack(cmd)

    def _send_with_no_ack(self, cmd):
        for char in cmd:
            self._ru._send(char)
            if char != "\r":
                time.sleep(0.01)
            self._raise_if_not_sending_state()

    def _ping(self):
        self._session_logger.log_write("<ENTER>")
        with suppress(RMODBusyError, ConnectionError):
            self._send_with_no_ack("")

    def _drain_output_queue(self):
        result = ""
        while True:
            try:
                result += self._active_output_queue.popleft()
            except IndexError:
                break
        return result

    def _wait_for_char_echo(self, expected_char, echo_buffer):
        deadline = time.monotonic() + self._echo_timeout
        while time.monotonic() < deadline:
            self._poll_rmod()
            echo_buffer += self._drain_output_queue()
            self._raise_if_not_sending_state(echo_buffer)
            if expected_char in echo_buffer:
                idx = echo_buffer.index(expected_char)
                for c in reversed(echo_buffer[:idx]):
                    self._active_output_queue.appendleft(c)
                return True, echo_buffer[idx + 1 :]
            time.sleep(0.001)
        return False, echo_buffer

    def _send_char_with_echo_ack(self, expected_char, echo_buffer):
        for attempt in range(self._echo_retry_count + 1):
            self._ru._send(expected_char)
            found, echo_buffer = self._wait_for_char_echo(expected_char, echo_buffer)
            if found:
                return echo_buffer
        self._session_logger.log_debug(
            f"Echo timeout for: {repr(expected_char)} after {self._echo_retry_count + 1} attempt(s)"
        )
        return echo_buffer

    def _send_with_echo_ack(self, cmd):
        echo_buffer = ""
        self._start_active_reading()
        try:
            for expected_char in cmd:
                if expected_char == "\r":
                    self._ru._send(expected_char)
                    continue
                echo_buffer = self._send_char_with_echo_ack(expected_char, echo_buffer)
            for char in reversed(echo_buffer):
                self._active_output_queue.appendleft(char)
        finally:
            self._stop_active_reading()

    def execute_cmd(self, cmd, elevated=False, timeout=30, wait_echo=True):
        self._wait_for_sending_state(self.connection_timeout if self.connection_timeout > timeout else timeout)
        with self._connector_mutex:
            self._start_active_reading()
            try:
                output, timedout = self._execute(cmd, elevated, timeout, wait_echo=wait_echo)
                if not timedout and (output == "" or output == cmd):
                    return self._execute("", timeout=timeout, wait_echo=wait_echo)
                return output, timedout
            finally:
                self._stop_active_reading()

    def _execute(self, cmd, elevated=False, timeout=30, wait_echo=True):
        if elevated:
            cmd = self._elevate_command(cmd)
        self._send(cmd, wait_echo=wait_echo)
        return self._read_output_until([self.shell_prompt_regex], [cmd], timeout=timeout)

    def _execute_cmd_for_login_procedure(
        self, cmd, timeout, extra_prompts=None, include_pattern_in_output=False, wait_echo=True
    ):
        self._wait_for_sending_state(self.connection_timeout if self.connection_timeout > timeout else timeout)
        with self._connector_mutex:
            self._start_active_reading()
            try:
                expected_prompts = [self.shell_prompt_regex]
                if extra_prompts is not None:
                    expected_prompts.extend(extra_prompts)
                self._send(cmd, wait_echo=wait_echo, skip_log_in=True)
                return self._read_output_until(
                    expected_prompts, [cmd], timeout=timeout, include_pattern_in_output=include_pattern_in_output
                )
            finally:
                self._stop_active_reading()

    def _read_output_until(self, expect_patterns, ignore_patterns, include_pattern_in_output=False, timeout=3):
        output = ""
        stop_time = time.monotonic() + timeout
        while time.monotonic() < stop_time:
            self._poll_rmod()

            drained = self._drain_output_queue()
            output += drained

            if not drained:
                time.sleep(0.01)
                continue

            output_after_match = self._match_expected_patterns(expect_patterns, output, include_pattern_in_output)
            if output_after_match is not None:
                if self._should_msg_be_ignored(output_after_match.strip(), ignore_patterns):
                    return "", False
                return output_after_match, False
        return output.strip(), True

    @staticmethod
    def _should_msg_be_ignored(msg, ignore_patterns):
        if not msg:
            return True
        for pattern in filter(bool, ignore_patterns):
            matched = re.match(f"^{re.escape(pattern[0])}?{re.escape(msg)}(.*)", pattern.strip())
            if matched:
                if len(msg) < len(pattern):
                    ignore_patterns.append(msg[-1] + matched.group(1))
                ignore_patterns.remove(pattern)
                return True
        return False

    @staticmethod
    def _match_expected_patterns(patterns, output, include_pattern_in_output):
        for pattern in patterns:
            if DefaultRMODInterface._is_pattern_matched(pattern, output):
                if include_pattern_in_output:
                    return output.strip()
                return re.sub(pattern, "", output).strip()

    @staticmethod
    def _is_pattern_matched(pattern, output):
        if isinstance(pattern, re.Pattern):
            return pattern.search(output)
        else:
            return re.search(pattern, output)

    def collect_output(self):
        data = self._output_buffer
        self._output_buffer = ""
        return data

    def _elevate_command(self, cmd):
        return f"{'sudo -u rfsw ' if self.login == 'serviceuser' else ''}{cmd}"

    def disconnect(self):
        logger.debug(f"[{self._serial_number}] State at disconnect: {self._state}")
        self._disconnect_requested = True
        self._reader_thread.join(timeout=self._join_timeout)
        if self._reader_thread.is_alive():
            logger.warning(
                f"[{self._serial_number}] Reader thread did not exit within {self._join_timeout}s; "
                "closing connector anyway."
            )
        else:
            logger.debug(f"[{self._serial_number}] Reader thread joined.")
        self._ru.close()
        self._state.connected = False
        if self._exc:
            raise self._exc

    def get_state(self):
        return self._state.to_dict()


class RMODState:
    def __init__(self):
        self._state_mutex = Lock()
        self._connected = False
        self._logged_in = False
        self._uboot_detected = False
        self._login_possible = False
        self._console_blocked = False
        self._reboot_detected = False

    @property
    def connected(self):
        with self._state_mutex:
            return self._connected

    @connected.setter
    def connected(self, state):
        with self._state_mutex:
            self._connected = bool(state)

    @property
    def logged_in(self):
        with self._state_mutex:
            return self._logged_in

    @logged_in.setter
    def logged_in(self, state):
        with self._state_mutex:
            self._logged_in = bool(state)

    @property
    def uboot_detected(self):
        with self._state_mutex:
            return self._uboot_detected

    @uboot_detected.setter
    def uboot_detected(self, state):
        with self._state_mutex:
            self._uboot_detected = bool(state)

    @property
    def console_blocked(self):
        with self._state_mutex:
            return self._console_blocked

    @console_blocked.setter
    def console_blocked(self, state):
        with self._state_mutex:
            self._console_blocked = bool(state)

    @property
    def login_possible(self):
        with self._state_mutex:
            return self._login_possible

    @login_possible.setter
    def login_possible(self, state):
        with self._state_mutex:
            self._login_possible = bool(state)

    @property
    def reboot_detected(self):
        with self._state_mutex:
            return self._reboot_detected

    @reboot_detected.setter
    def reboot_detected(self, state):
        with self._state_mutex:
            self._reboot_detected = bool(state)

    @property
    def sending_possible(self):
        with self._state_mutex:
            return not (self._reboot_detected or self._uboot_detected or not self._connected)

    def to_dict(self):
        return {
            "connected": self.connected,
            "uboot_detected": self.uboot_detected,
            "logged_in": self.logged_in,
            "login_possible": self.login_possible,
            "console_blocked": self.console_blocked,
            "reboot_detected": self.reboot_detected,
        }

    def __str__(self):
        return str(self.to_dict())
